// Fence between the async destination accumulators of GMMA & source for their dependent use
template CUTE\_HOST\_DEVICE
void
warpgroup\_fence\_operand(Tensor& frg) {
CUTE\_STATIC\_ASSERT(is\_static::value);
if constexpr (is\_same\_v) {
auto f32\_frg = recast(frg);
CUTE\_UNROLL
for (int i = 0; i < size(f32\_frg); ++i) {
warpgroup\_fence\_operand(f32\_frg(i));
}
}
else {
CUTE\_STATIC\_ASSERT(is\_rmem::value);
auto u32\_frg = recast(frg);
CUTE\_UNROLL
for (int i = 0; i < size(u32\_frg); ++i) {
warpgroup\_fence\_operand(u32\_frg(i));
}
}
}
