using Layout\_MN\_SW128\_Atom\_Bits = ComposedLayout, smem\_ptr\_flag, Layout,Stride<\_1,\_1024>>>;
// K-major GMMA layouts in units of bits
using Layout\_K\_INTER\_Atom\_Bits = ComposedLayout, smem\_ptr\_flag, Layout,Stride< \_128,\_1>>>;
