//
// Tensor (position-dependent swizzle) to LayoutType utility
//
template CUTE\_HOST\_DEVICE constexpr
LayoutType
layout\_type(Tensor\> const&)
{
static\_assert(is\_same::value,
"Expected uint128\_t type in LayoutType conversion.");
using Swizzle = get\_swizzle\_t;
constexpr int B = Swizzle::num\_bits;
constexpr int M = Swizzle::num\_base;
constexpr int S = Swizzle::num\_shft;
static\_assert(M == 4, "Unsupported layout swizzle");
static\_assert(0 <= B && B <= 3, "Unsupported layout swizzle");
static\_assert(S == 3, "Unsupported layout swizzle");
switch (B) {
case 0: return LayoutType::INTERLEAVE;
case 1: return LayoutType::B32;
case 2: return LayoutType::B64;
case 3: return LayoutType::B128;
}
return LayoutType::INTERLEAVE; // ERROR
}
///////////////////////////////////////////////////////////////////////////////
// Construction method for GMMA Descriptors
///////////////////////////////////////////////////////////////////////////////
/\*\*
\* ///////////////////////////////
\* // make\_gmma\_desc //
\* ///////////////////////////////
\* Each GmmaDescriptor Major-MN describes a canonical layout of the form
\*
\* LayoutType::INTERLEAVE : Swizzle<0,4,3> o smem\_ptr o ((T,1,m),(8,k)):((1,T,SBO),(1T,LBO))
\* LayoutType::B32 : Swizzle<1,4,3> o smem\_ptr o ((T,2,m),(8,k)):((1,T,LBO),(2T,SBO))
\* LayoutType::B64 : Swizzle<2,4,3> o smem\_ptr o ((T,4,m),(8,k)):((1,T,LBO),(4T,SBO))
\* LayoutType::B128 : Swizzle<3,4,3> o smem\_ptr o ((T,8,m),(8,k)):((1,T,LBO),(8T,SBO))
\*
\* where
\* T : sizeof(uint128\_t) / sizeof(value\_type)
\* m : integer in \[1,16\] corresponding to GMMA shape
\* k : integer in \[1,32\] corresponding to GMMA shape
\* SBO: stride byte offset
\* LBO: leading byte offset
\*
\* See GMMA::Layout\_MN\_XXX\_Atom for building canonical GmmaDescriptor Major-MN layouts.
\* For example,
\* auto smem\_layout = tile\_to\_shape(Layout\_MN\_SW128\_Atom{}, Shape<\_128,\_64>{});
\* is guaranteed to be accepted by make\_gmma\_desc for appropriate value\_type.
\*
\* //////////////////////////////
\* // make\_gmma\_desc //
\* //////////////////////////////
\* Each GmmaDescriptor Major-K describes a canonical layout of the form
\*
\* LayoutType::INTERLEAVE : Swizzle<0,4,3> o smem\_ptr o ((8,m),(T,2)):((1T,SBO),(1,LBO))
\* LayoutType::B32 : Swizzle<1,4,3> o smem\_ptr o ((8,m),(T,2)):((2T,SBO),(1, T ))
\* LayoutType::B64 : Swizzle<2,4,3> o smem\_ptr o ((8,m),(T,2)):((4T,SBO),(1, T ))
\* LayoutType::B128 : Swizzle<3,4,3> o smem\_ptr o ((8,m),(T,2)):((8T,SBO),(1, T ))
\*
\* See GMMA::Layout\_K\_XXX\_Atom for building canonical GmmaDescriptor Major-K layouts.
\* For example,
\* auto smem\_layout = tile\_to\_shape(Layout\_K\_SW128\_Atom{}, Shape<\_128,\_64>{});
\* is guaranteed to be accepted by make\_gmma\_desc for appropriate value\_type.
\*/
template CUTE\_HOST\_DEVICE constexpr
GmmaDescriptor
make\_gmma\_desc(Tensor const& tensor)
{
static\_assert(is\_smem::value, "GMMA Descriptors can only be constructed on smem.");
static\_assert(TLayout::rank == 2, "GMMA Descriptors can only be constructed on rank-2 tensors.");
using value\_type = typename TEngine::value\_type;
Tensor u128\_tensor = recast(tensor);
// Result
GmmaDescriptor desc;
// Layout type
constexpr LayoutType LAYOUT\_TYPE = layout\_type(u128\_tensor);
desc.bitfield.layout\_type\_ = uint8\_t(LAYOUT\_TYPE);
// Start address (4LSB not included)
uint32\_t start\_address = cast\_smem\_ptr\_to\_uint(raw\_pointer\_cast(u128\_tensor.data()));
desc.bitfield.start\_address\_ = static\_cast(start\_address >> 4);
constexpr uint8\_t base\_offset = 0;
desc.bitfield.base\_offset\_ = base\_offset;
// LayoutType meta
constexpr int W = LAYOUT\_TYPE == LayoutType::INTERLEAVE ? 1 :
LAYOUT\_TYPE == LayoutType::B32 ? 2 :
LAYOUT\_TYPE == LayoutType::B64 ? 4 :
LAYOUT\_TYPE == LayoutType::B128 ? 8 : -1;
if constexpr (MajorMode == Major::MN)
{
/\* In units of uint128\_t, each GmmaDescriptor Major-MN describes a canonical layout of the form
\*
\* LayoutType::INTERLEAVE : Swizzle<0,4,3> o smem\_ptr o ((1,n),(8,k)):((X,SBO),(1,LBO))
\* LayoutType::B32 : Swizzle<1,4,3> o smem\_ptr o ((2,n),(8,k)):((1,LBO),(2,SBO))
\* LayoutType::B64 : Swizzle<2,4,3> o smem\_ptr o ((4,n),(8,k)):((1,LBO),(4,SBO))
\* LayoutType::B128 : Swizzle<3,4,3> o smem\_ptr o ((8,n),(8,k)):((1,LBO),(8,SBO))
\*/
static\_assert(size<1>(u128\_tensor) == Int<(256 / cute::sizeof\_bits::value)>{} || // A and B in dense MMA
size<1>(u128\_tensor) == Int<(128 / cute::sizeof\_bits::value)>{} || // A in sparse MMA
size<1>(u128\_tensor) == Int<(512 / cute::sizeof\_bits::value)>{}, // B in sparse MMA
"Not a canonical GMMA\_MN Layout: Expected K-size 256/sizeof\_bits for dense or (128|512)/sizeof\_bits for sparse.");
// Construct the canonical GMMA T Layout with shape ((W,n),(8,2))
Layout canonical\_layout = logical\_divide(layout(u128\_tensor), Tile,\_1>,Layout,\_1>>{});
// Check profile of canonical
CUTE\_STATIC\_ASSERT\_V(congruent(canonical\_layout, Shape,Shape<\_1,\_1>>{}), "Not a canonical GMMA\_MN Layout: Expected profile failure.");
// Check canonical mode strides
constexpr uint32\_t stride\_00 = stride<0,0>(canonical\_layout);
constexpr uint32\_t expected\_stride\_00 = LAYOUT\_TYPE == LayoutType::INTERLEAVE ? stride<0,0>(canonical\_layout) : 1;
static\_assert(stride\_00 == expected\_stride\_00, "Not a canonical GMMA\_MN Layout: Expected stride failure.");
constexpr uint32\_t stride\_10 = stride<1,0>(canonical\_layout);
constexpr uint32\_t expected\_stride\_10 = W;
static\_assert(stride\_10 == expected\_stride\_10, "Not a canonical GMMA\_MN Layout: Expected stride failure.");
// stride dimension byte offset and leading dimension byte offset (4LSB not included == uint128\_t units)
constexpr uint32\_t stride\_01 = stride<0,1>(canonical\_layout);
constexpr uint32\_t stride\_11 = stride<1,1>(canonical\_layout);
desc.bitfield.stride\_byte\_offset\_ = (LAYOUT\_TYPE == LayoutType::INTERLEAVE) ? stride\_01 : stride\_11;
desc.bitfield.leading\_byte\_offset\_ = (LAYOUT\_TYPE == LayoutType::INTERLEAVE) ? stride\_11 : stride\_01;
}
else if constexpr (MajorMode == Major::K)
{
/\* In units of uint128\_t, each GmmaDescriptor Major-K describes a canonical layout of the form
\*
\* LayoutType::INTERLEAVE : Swizzle<0,4,3> o smem\_ptr o ((8,n),2):((1,SBO),LBO)
\* LayoutType::B32 : Swizzle<1,4,3> o smem\_ptr o ((8,n),2):((2,SBO),1)
\* LayoutType::B64 : Swizzle<2,4,3> o smem\_ptr o ((8,n),2):((4,SBO),1)
\* LayoutType::B128 : Swizzle<3,4,3> o smem\_ptr o ((8,n),2):((8,SBO),1)
\*/
CUTE\_STATIC\_ASSERT\_V(size<0>(u128\_tensor) % Int<8>{} == Int<0>{}, // N|M size
"Not a canonical GMMA\_K Layout: Expected MN-size multiple of 8.");
CUTE\_STATIC\_ASSERT\_V(size<1>(u128\_tensor) == Int<2>{} || size<1>(u128\_tensor) == Int<4>{}, // K size
"Not a canonical GMMA\_K Layout: Expected K-size 2 for dense or 4 for sparse (in units of uint128\_t).");
// Construct the canonical GMMA N Layout with shape ((8,n),(2,1))
Layout canonical\_layout = logical\_divide(layout(u128\_tensor), Tile,Layout<\_2,\_1>>{});
// Check profile of canonical
CUTE\_STATIC\_ASSERT\_V(congruent(canonical\_layout, Shape,Shape<\_1,\_1>>{}), "Not a canonical GMMA\_K Layout: Expected profile failure.");
// Check canonical mode strides
constexpr uint32\_t stride\_00 = stride<0,0>(canonical\_layout);
constexpr uint32\_t expected\_stride\_00 = W;
static\_assert(stride\_00 == expected\_stride\_00, "Not a canonical GMMA\_K Layout: Expected stride failure.");
constexpr uint32\_t stride\_10 = stride<1,0>(canonical\_layout);
constexpr uint32\_t expected\_stride\_10 = (LAYOUT\_TYPE == LayoutType::INTERLEAVE) ? stride<1,0>(canonical\_layout) : 1;
static\_assert(stride\_10 == expected\_stride\_10, "Not a canonical GMMA\_K Layout: Expected stride failure.");
// stride dimension byte offset and leading dimension byte offset (4LSB not included == uint128\_t units)
constexpr uint32\_t stride\_01 = stride<0,1>(canonical\_layout);
desc.bitfield.stride\_byte\_offset\_ = stride\_01;
desc.bitfield.leading\_byte\_offset\_ = stride\_10;
} else {
static\_assert(MajorMode != Major::MN && MajorMode != Major::K, "Unrecognized MajorMode!");
}
return desc;
}
