// Higher level GMMA Descriptor utilities
///////////////////////////////////////////////////////////////////////////////
struct DescriptorIterator
{
using reference = GmmaDescriptor;
using element\_type = GmmaDescriptor;
using value\_type = GmmaDescriptor;
GmmaDescriptor desc\_;
// Dereference returns the GmmaDescriptor
CUTE\_HOST\_DEVICE constexpr
reference operator\*() const { return desc\_; }
// Advance and return a new GmmaDescriptor
template CUTE\_HOST\_DEVICE constexpr
reference operator\[\](Index const& i) const { return \*(\*this + i); }
// Return an advanced iterator
template CUTE\_HOST\_DEVICE constexpr
DescriptorIterator operator+(Index const& offset) const
{
// Use 32bit calculation rather than 64 bit calculation as we only update the part of desc
GmmaDescriptor ret;
ret.reg32\_\[0\] = desc\_.reg32\_\[0\] + uint32\_t(offset);
ret.reg32\_\[1\] = desc\_.reg32\_\[1\];
return { ret };
}
};
template CUTE\_HOST\_DEVICE constexpr
GmmaDescriptor
raw\_pointer\_cast(DescriptorIterator const& ptr) {
return ptr.desc\_;
}
// Recast a DescriptorIterator Tensor to uint64\_t, it's RegType in mma\_unpack
template CUTE\_HOST\_DEVICE constexpr
DescriptorIterator
recast\_ptr(DescriptorIterator const& iter) {
static\_assert(is\_same::value, "Can only cast GmmaDescriptorIterator to uint64\_t.");
return iter; // Do nothing, it will still dereference to GmmaDescriptor and decay to uint64\_t
}
CUTE\_HOST\_DEVICE void
print(DescriptorIterator) {
printf("GMMA::DescriptorIterator");
}
// The GMMA Traits below have custom fragment type flags for their smem desc tensors.
// These flags specialize a MakeTensor customization point to correctly make the fragment that is desired.
template struct smem\_desc : DescriptorIterator {};
} // end namespace SM90::GMMA
// Customization point for creating a GMMA::smem\_desc Tensor
template struct MakeTensor\>
{
template CUTE\_HOST\_DEVICE constexpr auto
operator()(Tensor const& smem\_tensor)
{
static\_assert(is\_smem::value, "Expected SMEM Tensor to construct a GMMA Desc Tensor");
return make\_tensor(SM90::GMMA::DescriptorIterator{SM90::GMMA::make\_gmma\_desc(tensor<0>(smem\_tensor))},
replace<0>(recast(smem\_tensor).layout(), Layout<\_1,\_0>{}));
}
};
