//
// Specialized mma\_unpack implementation for SM90 GMMA instructions
//
template CUTE\_HOST\_DEVICE constexpr
void
mma\_unpack(MMA\_Traits const& traits,
Tensor & D,
Tensor const& A,
Tensor const& B,
Tensor const& C)
{
static\_assert(is\_rmem ::value, "Expected registers in MMA\_Atom::call");
static\_assert(is\_rmem::value, "Expected registers in MMA\_Atom::call");
static\_assert(is\_rmem::value, "Expected registers in MMA\_Atom::call");
static\_assert(is\_rmem::value, "Expected registers in MMA\_Atom::call");
// Register value types from the MMA\_Operation register arrays
using RegTypeA = typename remove\_extent::type;
using RegTypeB = typename remove\_extent::type;
using RegTypeC = typename remove\_extent::type;
// SM90 GMMA take three arguments rather than four, try to assert C and D are aliased
static\_assert(is\_same::value, "GMMA C and D value\_type must match.");
static\_assert(is\_same::value, "GMMA C and D layouts must match.");
// assert((void\*)&C == (void\*)&D);
Tensor rA = recast(A);
Tensor rB = recast(B);
Tensor rC = recast(D); // NOTE: D and C are same, so use mutable D
constexpr int RegNumA = extent::value;
constexpr int RegNumB = extent::value;
constexpr int RegNumC = extent::value;
CUTE\_STATIC\_ASSERT\_V(size(rA) == Int{});
CUTE\_STATIC\_ASSERT\_V(size(rB) == Int{});
CUTE\_STATIC\_ASSERT\_V(size(rC) == Int{});
detail::explode(MMA\_Op::fma,
rA, make\_int\_sequence{},
rB, make\_int\_sequence{},
rC, make\_int\_sequence{},
&(traits.accumulate\_), seq<0>{});
}
